const teia = (cx, cy, r) => {
  const raios = Array.from({ length: 8 }, (_, i) => {
    const a = (i * Math.PI) / 4
    return `M${cx} ${cy} L${(cx + Math.cos(a) * r).toFixed(1)} ${(cy + Math.sin(a) * r).toFixed(1)}`
