.palco-balao h1 { position: relative; font-family: var(--titulo); font-weight: 700; font-size: 2.3rem; margin: 0 0 10px; }
.xp-linha { display: flex; align-items: center; gap: 10px; }
.xp-estrela { flex: none; color: var(--pessego); filter: drop-shadow(2px 2px 0 var(--contorno)); }
.xp-estrela svg { fill: #FFD166; stroke: var(--contorno); }
.xp { flex: 1; height: 26px; border-radius: 999px; background: #EFE3D3; border: 3px solid var(--contorno); overflow: hidden; }
.xp span { display: block; height: 100%; border-radius: 999px; background: var(--tema); box-shadow: inset 0 -5px 0 rgba(0, 0, 0, 0.12); transition: width 300ms ease; }
.xp-proximo { flex: none; width: 56px; height: 56px; padding: 5px; border-radius: 14px; background: #fff; border: 3px dashed var(--contorno); transform: rotate(4deg); }
.xp-texto { margin: 8px 0 0; color: var(--suave); }
.xp-texto strong { color: var(--tinta); }

/* Escolha do tema */
.grade-temas { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 22px; margin-bottom: 24px; }
.crianca .cartao-tema { flex-direction: column; gap: 0; padding: 0; min-height: 0; overflow: hidden; border: 3px solid var(--contorno); border-radius: 24px; background: var(--papel-creme); box-shadow: var(--sombra-papel); transition: transform 150ms ease, box-shadow 150ms ease; }
.crianca .cartao-tema:nth-child(odd) { transform: rotate(-1deg); }
.crianca .cartao-tema:nth-child(even) { transform: rotate(1deg); }
.crianca .cartao-tema:hover { transform: rotate(0) translateY(-3px); }
.crianca .cartao-tema:active { transform: translate(3px, 3px); box-shadow: 0 0 0 var(--contorno); }
.cartao-tema-arte { width: 100%; display: grid; place-items: center; padding: 18px; background: var(--ceu); border-bottom: 3px solid var(--contorno); }
.cartao-tema-arte img { width: 130px; height: 130px; filter: var(--adesivo); }
.cartao-tema-nome { padding: 14px; font-family: var(--titulo); font-weight: 700; font-size: 1.4rem; color: var(--tinta); }

/* Cartões de jogo: papel levemente inclinado, capa grande e botão de jogar. */
.grade-jogos { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 26px 22px; }
.crianca .cartao-jogo { flex-direction: column; align-items: stretch; gap: 0; padding: 0; min-height: 0; overflow: hidden; border: 3px solid var(--contorno); border-radius: 26px; background: var(--papel-creme); box-shadow: var(--sombra-papel); text-align: left; transition: transform 150ms ease, box-shadow 150ms ease; }
.crianca .cartao-jogo:nth-child(odd) { transform: rotate(-1deg); }
.crianca .cartao-jogo:nth-child(even) { transform: rotate(1deg); }
.crianca .cartao-jogo:hover { transform: rotate(0) translateY(-3px); }
.crianca .cartao-jogo:active { transform: translate(3px, 3px); box-shadow: 0 0 0 var(--contorno); }
.cartao-jogo-capa { position: relative; display: grid; place-items: center; height: 170px; border-bottom: 3px solid var(--contorno); background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6) 0 60px, transparent 61px), var(--ceu); }
.capa-1 .cartao-jogo-capa { background: radial-gradient(circle at 75% 70%, rgba(255, 255, 255, 0.6) 0 70px, transparent 71px), var(--pessego-claro); }
.capa-2 .cartao-jogo-capa { background: radial-gradient(circle at 25% 75%, rgba(255, 255, 255, 0.6) 0 64px, transparent 65px), var(--rubi-claro); }
.cartao-jogo-capa img { width: 124px; height: 124px; filter: var(--adesivo); }
.cartao-jogo-tipo { position: absolute; top: 12px; left: 12px; width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; background: var(--papel-creme); color: var(--tinta); border: 3px solid var(--contorno); box-shadow: 2px 2px 0 var(--contorno); }
.cartao-jogo-rodape { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 14px 14px 18px; }
.cartao-jogo-nome { font-family: var(--titulo); font-weight: 700; font-size: 1.3rem; line-height: 1.2; }
.cartao-jogo-play { flex: none; width: 54px; height: 54px; border-radius: 50%; display: grid; place-items: center; background: var(--tema); color: #fff; border: 3px solid var(--contorno); box-shadow: 2px 2px 0 var(--contorno); transition: background-color 150ms ease; }
.cartao-jogo-play svg { fill: #fff; }
.crianca .cartao-jogo:hover .cartao-jogo-play { background: color-mix(in srgb, var(--tema) 85%, #000); }
.crianca-vazio { display: flex; align-items: center; gap: 16px; margin: 0; padding: 20px; border-radius: 20px; background: var(--papel-creme); border: 3px solid var(--contorno); box-shadow: var(--sombra-papel); }
.crianca-vazio img { filter: var(--adesivo); }

/* Coleção: estante com o item ganho, o próximo e os bloqueados (silhueta). */
.estante { list-style: none; margin: 0; padding: 20px; display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 14px; border-radius: 26px; background: var(--papel-creme); border: 3px solid var(--contorno); box-shadow: var(--sombra-papel); }
.item-colecao { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 8px; border-radius: 18px; text-align: center; font-size: 0.95rem; font-weight: 700; line-height: 1.2; }
.item-colecao img { width: 72px; height: 72px; }
.item-colecao.ganho { background: var(--tema-fundo); }
.item-colecao.proximo { border: 2px dashed var(--tema); color: var(--tema); }
.item-colecao.proximo img { opacity: 0.4; filter: grayscale(1); }
.item-colecao.bloqueado { background: #F6F0EA; color: var(--suave); }
.item-colecao.bloqueado img { filter: brightness(0); opacity: 0.12; }

