/* Barra de XP com o personagem do tema (exceção de movimento do DESIGN.md).
   Barra e personagem andam juntos por transform: o preenchimento ocupa a barra toda e é
   empurrado para a esquerda; a guia tem a largura da barra e leva o personagem na ponta. */
.xp-trilho { position: relative; flex: 1; margin-top: 40px; }
.xp-preenchido { display: block; width: 100%; height: 100%; border-radius: 999px; background: var(--tema); box-shadow: inset 0 -5px 0 rgba(0, 0, 0, 0.12); transform: translateX(calc(var(--pct) - 100%)); animation: xp-avancar 1s var(--ease-in-out) both; }
.xp-guia { position: absolute; left: 0; right: 0; bottom: 20px; height: 0; pointer-events: none; transform: translateX(calc(var(--pct) - 100%)); animation: xp-avancar 1s var(--ease-in-out) both; }
.xp-personagem { position: absolute; right: 0; bottom: 0; width: 48px; height: 48px; translate: 50% 0; filter: var(--adesivo); animation: xp-respirar 1.5s ease-in-out 1s infinite alternate both; }
@keyframes xp-avancar { from { transform: translateX(-100%); } }
@keyframes xp-respirar { from { transform: translateY(0); } to { transform: translateY(-2px); } }
.xp-proximo { flex: none; width: 56px; height: 56px; padding: 5px; margin-bottom: -15px; border-radius: 14px; background: #fff; border: 3px dashed var(--contorno); transform: rotate(4deg); }

