// Ponte local: recebe as chamadas do Vite em 127.0.0.1:3001 e repassa ao servidor no Render.
// Só para testar o site local com os dados reais (o Render só aceita CORS do GitHub Pages).
import http from 'node:http'

const ALVO = 'https://hackaton-dopamine.onrender.com'

http
  .createServer(async (req, res) => {
    const partes = []
    for await (const p of req) partes.push(p)
    const headers = { ...req.headers }
    delete headers.host
    delete headers.origin
    delete headers.referer
    delete headers['content-length']
    try {
      const r = await fetch(ALVO + req.url, {
        method: req.method,
        headers,
        body: ['GET', 'HEAD'].includes(req.method) ? undefined : Buffer.concat(partes),
      })
      const corpo = Buffer.from(await r.arrayBuffer())
      res.writeHead(r.status, { 'content-type': r.headers.get('content-type') ?? 'application/json' })
      res.end(corpo)
    } catch (e) {
      res.writeHead(502, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ erro: 'Ponte: não consegui falar com o Render.' }))
    }
  })
  .listen(3001, '127.0.0.1', () => console.log('ponte pronta em http://127.0.0.1:3001 ->', ALVO))

