86:.capa { position: relative; flex: none; width: 260px; height: 168px; border-radius: 18px; overflow: hidden; background: var(--ceu); }
87:.capa-chao { position: absolute; left: -10%; right: -10%; bottom: -30px; height: 96px; border-radius: 50% 50% 0 0; background: var(--chao); }
88:.capa-item { position: absolute; right: 14px; top: 10px; width: 92px; height: 92px; }
89:.capa-personagem { position: absolute; left: 10px; top: 8px; width: 84px; height: 84px; }
90:.capa-rodape { position: absolute; left: 10px; right: 10px; bottom: 10px; display: flex; align-items: center; gap: 10px; padding: 6px 12px 6px 6px; border-radius: 12px; background: rgba(255, 255, 255, 0.92); }
91:.capa-rodape img { flex: none; width: 36px; height: 36px; border-radius: 9px; object-fit: contain; }
92:.capa-rodape span { display: flex; flex-direction: column; line-height: 1.15; min-width: 0; }
93:.capa-rodape strong { font-family: var(--titulo); font-weight: 600; color: var(--tinta); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
94:.capa-rodape small { color: var(--suave); font-size: 0.8rem; }
95:/* Marca no centro: as capas atrás dela ficam desfocadas e um pouco mais escuras (profundidade de campo,
97:   creme de adesivo e uma sombra firme embaixo, para ler bem sobre qualquer capa. */
250:.cor-verde { background: var(--verde-claro); } .cor-verde .topico-icone, .sugestao-capa.cor-verde, .lista-jogos-icone.cor-verde { color: var(--verde-forte); }
251:.cor-rubi { background: var(--rubi-claro); } .cor-rubi .topico-icone, .sugestao-capa.cor-rubi, .lista-jogos-icone.cor-rubi { color: var(--rubi-forte); }
252:.cor-pessego { background: var(--pessego-claro); } .cor-pessego .topico-icone, .sugestao-capa.cor-pessego, .lista-jogos-icone.cor-pessego { color: var(--alerta); }
268:.sugestao-capa { position: relative; height: 110px; display: grid; place-items: center; }
269:.sugestao-capa .selo { position: absolute; top: 10px; right: 10px; background: var(--cartao); }
388:/* Cartões de jogo: papel levemente inclinado, capa grande e botão de jogar. */
395:.cartao-jogo-capa { position: relative; display: grid; place-items: center; height: 170px; border-bottom: 3px solid var(--contorno); background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6) 0 60px, transparent 61px), var(--ceu); }
396:.capa-1 .cartao-jogo-capa { background: radial-gradient(circle at 75% 70%, rgba(255, 255, 255, 0.6) 0 70px, transparent 71px), var(--pessego-claro); }
397:.capa-2 .cartao-jogo-capa { background: radial-gradient(circle at 25% 75%, rgba(255, 255, 255, 0.6) 0 64px, transparent 65px), var(--rubi-claro); }
398:.cartao-jogo-capa img { width: 124px; height: 124px; filter: var(--adesivo); }
407:.capa-svg { position: absolute; inset: 0; display: block; width: 100%; height: 100%; overflow: visible; }
408:.capa-svg image { filter: drop-shadow(1.5px 0 0 #fff) drop-shadow(-1.5px 0 0 #fff) drop-shadow(0 1.5px 0 #fff) drop-shadow(0 -1.5px 0 #fff); }
409:.capa-frente, .capa-verso, .capa-pergunta, .capa-resposta { transform-box: fill-box; transform-origin: center; }
411:.capa-memoria .capa-frente { transform: scaleX(0); transition: transform 130ms var(--ease-in-out); }
412:.capa-memoria .capa-verso { transition: transform 130ms var(--ease-in-out) 130ms; }
414:.capa-sequencia .capa-pergunta { transition: opacity 120ms var(--ease-out), transform 120ms var(--ease-out) 60ms; }
415:.capa-sequencia .capa-resposta { opacity: 0; transform: scale(0.9); transition: opacity 120ms var(--ease-out), transform 120ms var(--ease-out); }
