file.content:
/* Capas dos jogos (CapaJogo.jsx): um gesto curto quando a criança aponta para o cartão.
   Sem loop; com movimento reduzido a troca é instantânea. */
.capa-svg { position: absolute; inset: 0; display: block; width: 100%; height: 100%; overflow: visible; }
.capa-svg image { filter: drop-shadow(1.5px 0 0 #fff) drop-shadow(-1.5px 0 0 #fff) drop-shadow(0 1.5px 0 #fff) drop-shadow(0 -1.5px 0 #fff); }
.capa-frente, .capa-verso, .capa-pergunta, .capa-resposta { transform-box: fill-box; transform-origin: center; }
/* Memória: a carta vira em duas metades (fecha o verso, abre a frente) = 260 ms. */
.capa-memoria .capa-frente { transform: scaleX(0); transition: transform 130ms var(--ease-in-out); }
.capa-memoria .capa-verso { transition: transform 130ms var(--ease-in-out) 130ms; }
/* Sequência: o "?" some e o item certo aparece no lugar = 260 ms. */
.capa-sequencia .capa-pergunta { transition: opacity 120ms var(--ease-out), transform 120ms var(--ease-out) 60ms; }
.capa-sequencia .capa-resposta { opacity: 0; transform: scale(0.9); transition: opacity 120ms var(--ease-out), transform 120ms var(--ease-out); }
.cartao-jogo:focus-visible .capa-memoria .capa-verso { transform: scaleX(0); transition-delay: 0ms; }
.cartao-jogo:focus-visible .capa-memoria .capa-frente { transform: scaleX(1); transition-delay: 130ms; }
.cartao-jogo:focus-visible .capa-sequencia .capa-pergunta { opacity: 0; transform: scale(0.9); transition-delay: 0ms; }
.cartao-jogo:focus-visible .capa-sequencia .capa-resposta { opacity: 1; transform: scale(1); transition: opacity 180ms var(--ease-out) 80ms, transform 180ms var(--ease-out) 80ms; }
@media (hover: hover) and (pointer: fine) {
  .cartao-jogo:hover .capa-memoria .capa-verso { transform: scaleX(0); transition-delay: 0ms; }
  .cartao-jogo:hover .capa-memoria .capa-frente { transform: scaleX(1); transition-delay: 130ms; }
  .cartao-jogo:hover .capa-sequencia .capa-pergunta { opacity: 0; transform: scale(0.9); transition-delay: 0ms; }
  .cartao-jogo:hover .capa-sequencia .capa-resposta { opacity: 1; transform: scale(1); transition: opacity 180ms var(--ease-out) 80ms, transform 180ms var(--ease-out) 80ms; }
}

