/* Quebra-cabeça: a peça desliza e encaixa no buraco = 260 ms. */
.capa-quebra .capa-peca { transform-box: fill-box; transform-origin: center; transform: translate(70px, 6px) rotate(10deg); transition: transform 260ms var(--ease-out); }
/* Chuva de emoções: o rosto alegre cai dentro do balde = 240 ms. */
.capa-chuva .capa-rosto-cai { transition: transform 240ms var(--ease-in-out); }
/* Cuidar do amigo: o coração vai até o amigo (220 ms) e ele dá um pulinho no fim = 280 ms. */
.capa-cuidar .capa-coracao { transition: transform 220ms var(--ease-in-out); }
.capa-cuidar .capa-amigo { transition: transform 120ms var(--ease-out); }
