async (page) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.route('**/api/**', (r) => {
    const jogos = ['memoria','sequencia','quebra-cabeca','chuva-emocoes','cuidar-amigo','plataforma-amigo'].map((id) => ({ id, nome: { memoria:'Memória', sequencia:'Sequência', 'quebra-cabeca':'Quebra-cabeça', 'chuva-emocoes':'Chuva de emoções', 'cuidar-amigo':'Cuidar do amigo', 'plataforma-amigo':'Plataforma do amigo' }[id] }));
    r.fulfill({ json: { aluno: { id: 'a1', nome: 'Ana', hiperfoco: 'trem' }, xp: 30, jogos } });
  });
  await page.goto('http://localhost:5180/');
  await page.evaluate(() => localStorage.setItem('dopamine-usuario', JSON.stringify({ id: 'u1', papel: 'crianca', aluno_id: 'a1', nome: 'Ana' })));
  await page.goto('http://localhost:5180/#/crianca');
  await page.reload();
  await page.waitForSelector('.grade-jogos');
  const g = await page.$('.grade-jogos');
  await g.scrollIntoViewIfNeeded();
  await g.screenshot({ path: 'C:/Users/migue/AppData/Local/Temp/claude/C--Users-migue-Documents-hackathon-dopamine/70e25e93-6a3c-49bb-83f5-8e8d9350ad74/scratchpad/capas-repouso.png' });
  const erros = [];
  page.on('console', (m) => m.type() === 'error' && erros.push(m.text()));
  return erros;
}

