async (page) => {
  const dir = 'C:/Users/migue/AppData/Local/Temp/claude/C--Users-migue-Documents-hackathon-dopamine/70e25e93-6a3c-49bb-83f5-8e8d9350ad74/scratchpad/';
  const nomes = { memoria:'Memória', sequencia:'Sequência', 'quebra-cabeca':'Quebra-cabeça', 'chuva-emocoes':'Chuva de emoções', 'cuidar-amigo':'Cuidar do amigo', 'plataforma-amigo':'Plataforma do amigo' };
  let tema = 'trem';
  await page.unroute('**/api/**');
  await page.route('**/api/**', (r) => r.fulfill({ json: { aluno: { id: 'a1', nome: 'Ana', hiperfoco: tema }, xp: 30, jogos: Object.entries(nomes).map(([id, nome]) => ({ id, nome })) } }));
  const erros = [];
  page.on('pageerror', (e) => erros.push(String(e)));
  page.on('console', (m) => m.type() === 'error' && erros.push(m.text()));
  await page.setViewportSize({ width: 1280, height: 900 });
  const resultado = {};
  for (const t of ['trem', 'aranha', 'aviao', 'dinossauro']) {
    tema = t;
    await page.reload();
    await page.waitForSelector('.grade-jogos');
    await page.mouse.move(2, 2);
    await page.waitForTimeout(600);
    const g = await page.$('.grade-jogos');
    await g.scrollIntoViewIfNeeded();
    await g.screenshot({ path: dir + `todos-${t}-repouso.png` });
    // força o estado de hover em todos os cartões ao mesmo tempo
    await page.evaluate(() => {
      const css = [];
      for (const s of document.styleSheets) { let rs; try { rs = s.cssRules } catch { continue }
        for (const r of rs) if (r.media && r.conditionText?.includes('hover')) for (const i of r.cssRules) if (i.selectorText?.includes(':hover .capa')) css.push(i.cssText.replace(/:hover/g, ''));
      }
      const st = document.createElement('style'); st.id = 'forca'; st.textContent = css.join('\n'); document.head.append(st);
    });
    await page.waitForTimeout(600);
    await g.screenshot({ path: dir + `todos-${t}-gesto.png` });
    resultado[t] = await page.evaluate(() => ({
      capas: document.querySelectorAll('.capa-svg').length,
      imagensQuebradas: [...document.querySelectorAll('.capa-svg image')].filter((i) => !i.getAttribute('href')).length,
      clipIds: [...document.querySelectorAll('.capa-svg clipPath')].map((c) => c.id),
    }));
    await page.evaluate(() => document.getElementById('forca')?.remove());
  }
  // teclado: Tab até o cartão do quebra-cabeça
  tema = 'trem';
  await page.reload(); await page.waitForSelector('.grade-jogos');
  await page.focus('.cartao-jogo:nth-child(3)');
  await page.keyboard.press('Shift+Tab'); await page.keyboard.press('Tab');
  await page.waitForTimeout(500);
  resultado.tecladoPeca = await page.evaluate(() => getComputedStyle(document.querySelector('.capa-peca')).transform);
  // celular + movimento reduzido em todos os temas
  await page.setViewportSize({ width: 390, height: 844 });
  await page.emulateMedia({ reducedMotion: 'reduce' });
  resultado.celular = {};
  for (const t of ['trem', 'aranha', 'aviao', 'dinossauro']) {
    tema = t; await page.reload(); await page.waitForSelector('.grade-jogos');
    resultado.celular[t] = await page.evaluate(() => ({ larguraPagina: document.documentElement.scrollWidth, transicao: getComputedStyle(document.querySelector('.capa-pulo-x')).transitionDuration }));
  }
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.setViewportSize({ width: 1280, height: 900 });
  tema = 'trem'; await page.reload(); await page.waitForSelector('.grade-jogos');
  (await page.$('.grade-jogos')).scrollIntoViewIfNeeded();
  resultado.erros = erros;
  return resultado;
}

